SELECT FROM av_workflow_template t LEFT JOIN av_workflow_execution_config c ON c.tenant_id = t.tenant_id AND c.template_id = t.template_id AND c.del_flag = '0' LEFT JOIN av_runninghub_account a ON a.tenant_id = t.tenant_id AND a.account_id = c.runninghub_account_id AND a.del_flag = '0' LEFT JOIN sys_dict_data cat ON cat.dict_type = 'aivideo_discovery_category' AND cat.dict_value = CAST(t.category_id AS CHAR) WHERE t.tenant_id = #{tenantId} AND t.del_flag = '0'
AND t.channel = #{query.channel}
AND t.status = #{query.status}
AND t.category_id = #{query.categoryId}
AND t.recommended = #{query.recommended}
AND (t.name LIKE CONCAT('%', #{query.keyword}, '%') OR t.slug LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY t.name ASC, t.template_id DESC
ORDER BY t.sort_no ASC, t.template_id DESC
ORDER BY t.update_time DESC, t.template_id DESC

SELECT 
FROM av_workflow_template t


  AND t.template_id = #{templateId}

mapper.update:
UPDATE av_workflow_template
SET status = #{status},
    enabled_at = CASE WHEN #{setEnabledAt} THEN NOW() ELSE enabled_at END,
    update_by = #{actorId}, update_time = NOW(), row_revision = row_revision + 1
WHERE tenant_id = #{tenantId} AND template_id = #{templateId}
  AND del_flag = '0' AND row_revision = #{expectedRevision}
